@model(
    name="raw.accounts",
    strategy="merge",
    key=("_source_file", "_row"),
    cursor="dt",
    depends_on=("raw.files",),
    schedule={"cron": "30 5 * * 2-6"},
    tags=("sei", "raw", "snapshot"),
    description="SEI Accounts report (daily snapshot)",
)
async def raw_accounts(cursor: Any) -> pa.Table:
    return await read_report(
        "accounts",
        cursor,
        # The shape of the empty table when SEI has never delivered this report. Stated HERE, in
        # the model, because interlace fingerprints a model from its own source and nothing it
        # calls — a shape declared only in the helper cannot rebuild the table it got wrong.
        empty_columns=("_source_file", "_row", "dt"),
        sql="""
        SELECT
            * EXCLUDE (filename) REPLACE (
                try_strptime("ACCOUNT_INCEPTION_DATE", '%Y%m%d')::DATE AS "ACCOUNT_INCEPTION_DATE",
                try_strptime("ACCOUNT_OPEN_DATE", '%Y%m%d')::DATE AS "ACCOUNT_OPEN_DATE",
                CASE "CURR_MOVEMENT_STD_PKG_APPLIED" WHEN 'Y' THEN true WHEN 'N' THEN false END
                    AS "CURR_MOVEMENT_STD_PKG_APPLIED",
                try_strptime("DATE_LAST_UPDATED", '%Y%m%d')::DATE AS "DATE_LAST_UPDATED",
                try_strptime("DATE_PORTFOLIO_OPENED", '%Y%m%d')::DATE AS "DATE_PORTFOLIO_OPENED",
                CASE "DORMANT_STATUS_FLAG" WHEN 'Y' THEN true WHEN 'N' THEN false END
                    AS "DORMANT_STATUS_FLAG",
                CASE "FREE_MOVEMENT_STD_PKG_APPLIED" WHEN 'Y' THEN true WHEN 'N' THEN false END
                    AS "FREE_MOVEMENT_STD_PKG_APPLIED",
                CASE "FROZEN_STATUS_FLAG" WHEN 'Y' THEN true WHEN 'N' THEN false END
                    AS "FROZEN_STATUS_FLAG",
                try_cast("ISA_CONTRIBUTION_TO_DATE" AS DECIMAL(38, 10))
                    AS "ISA_CONTRIBUTION_TO_DATE",
                try_cast("ISA_WITHDRAWAL_TO_DATE" AS DECIMAL(38, 10)) AS "ISA_WITHDRAWAL_TO_DATE",
                try_strptime("LAST_TRADE_DATE", '%Y%m%d')::DATE AS "LAST_TRADE_DATE",
                CASE "RDR_RETENTION_FLAG" WHEN 'Y' THEN true WHEN 'N' THEN false END
                    AS "RDR_RETENTION_FLAG",
                try_cast("SIPP_CRYSTALLISED_VALUE" AS DECIMAL(38, 10)) AS "SIPP_CRYSTALLISED_VALUE",
                try_cast("SIPP_UNCRYSTALLISED_VALUE" AS DECIMAL(38, 10))
                    AS "SIPP_UNCRYSTALLISED_VALUE",
                CASE "TRADING_FEE_STD_PKG_APPLIED" WHEN 'Y' THEN true WHEN 'N' THEN false END
                    AS "TRADING_FEE_STD_PKG_APPLIED",
                CASE "VAT_ELIGIBLE_FLAG" WHEN 'Y' THEN true WHEN 'N' THEN false END
                    AS "VAT_ELIGIBLE_FLAG",
                CASE "W9_ON_FILE_FLG" WHEN 'Y' THEN true WHEN 'N' THEN false END
                    AS "W9_ON_FILE_FLG"
            ),
            filename AS _source_file,
            row_number() OVER (PARTITION BY filename) AS _row
        FROM read_csv(
            's3://{bucket}/sei/staged/accounts/dt=*/*.out',
            delim = '|',
            header = true,
            all_varchar = true,
            filename = true,
            hive_partitioning = true,
            union_by_name = true,
            quote = '',
            escape = '',
            null_padding = true,
            max_line_size = 16000000
        )
        """,
    )


