@model(
    name="raw.assets",
    strategy="merge",
    key=("_source_file", "_row"),
    cursor="dt",
    depends_on=("raw.files",),
    schedule={"cron": "30 5 * * 2-6"},
    tags=("sei", "raw", "snapshot"),
    description="SEI Assets report (daily snapshot)",
)
async def raw_assets(cursor: Any) -> pa.Table:
    return await read_report(
        "assets",
        cursor,
        # The shape of the empty table when SEI has never delivered this report. Stated HERE, in
        # the model, because interlace fingerprints a model from its own source and nothing it
        # calls — a shape declared only in the helper cannot rebuild the table it got wrong.
        empty_columns=("_source_file", "_row", "dt"),
        sql="""
        SELECT
            * EXCLUDE (filename) REPLACE (
                try_cast("ACCRUAL_FACTOR" AS DECIMAL(38, 10)) AS "ACCRUAL_FACTOR",
                CASE "CALLABLE_FLAG" WHEN 'Y' THEN true WHEN 'N' THEN false END AS "CALLABLE_FLAG",
                try_strptime("CALL_DATE", '%Y%m%d')::DATE AS "CALL_DATE",
                try_cast("CLEAN_PRICE" AS DECIMAL(38, 10)) AS "CLEAN_PRICE",
                try_cast("COUPON_RATE" AS DECIMAL(38, 10)) AS "COUPON_RATE",
                try_strptime("EXPIRY_DATE", '%Y%m%d')::DATE AS "EXPIRY_DATE",
                CASE "FLOATING_RATE_FLAG" WHEN 'Y' THEN true WHEN 'N' THEN false END
                    AS "FLOATING_RATE_FLAG",
                try_cast("INFLATION_FACTOR" AS DECIMAL(38, 10)) AS "INFLATION_FACTOR",
                try_strptime("INSTRUMENT_STATUS_DT", '%Y%m%d')::DATE AS "INSTRUMENT_STATUS_DT",
                try_cast("INTEREST_RATE" AS DECIMAL(38, 10)) AS "INTEREST_RATE",
                try_strptime("INTEREST_START_DATE", '%Y%m%d')::DATE AS "INTEREST_START_DATE",
                try_strptime("ISSUE_DATE", '%Y%m%d')::DATE AS "ISSUE_DATE",
                try_strptime("MATURITY_DATE", '%Y%m%d')::DATE AS "MATURITY_DATE",
                CASE "MIFID_COMPLEX_ASSET_INDICATOR" WHEN 'Y' THEN true WHEN 'N' THEN false END
                    AS "MIFID_COMPLEX_ASSET_INDICATOR",
                CASE "MIFID_LEVERAGED_INSTRUMENT_INDICATOR"
                    WHEN 'Y' THEN true WHEN 'N' THEN false END
                    AS "MIFID_LEVERAGED_INSTRUMENT_INDICATOR",
                CASE "MIFID_LIQUIDITY_INDICATOR" WHEN 'Y' THEN true WHEN 'N' THEN false END
                    AS "MIFID_LIQUIDITY_INDICATOR",
                CASE "MIFID_PROTECTED_INDICATOR" WHEN 'Y' THEN true WHEN 'N' THEN false END
                    AS "MIFID_PROTECTED_INDICATOR",
                CASE "MIFID_VENDOR_PRICED_INDICATOR" WHEN 'Y' THEN true WHEN 'N' THEN false END
                    AS "MIFID_VENDOR_PRICED_INDICATOR",
                try_cast("MIN_HOLDING_AMT" AS DECIMAL(38, 10)) AS "MIN_HOLDING_AMT",
                try_cast("MIN_INVESTMENT_AMT" AS DECIMAL(38, 10)) AS "MIN_INVESTMENT_AMT",
                try_cast("MIN_TRADE_AMT" AS DECIMAL(38, 10)) AS "MIN_TRADE_AMT",
                try_cast("MIN_TRADE_INCREMENT" AS DECIMAL(38, 10)) AS "MIN_TRADE_INCREMENT",
                try_strptime("NEXT_SCHEDULED_CALL_DATE", '%Y%m%d')::DATE
                    AS "NEXT_SCHEDULED_CALL_DATE",
                CASE "OPEN_TO_NEW_INVESTMENT_FLG" WHEN 'Y' THEN true WHEN 'N' THEN false END
                    AS "OPEN_TO_NEW_INVESTMENT_FLG",
                CASE "OPEN_TO_NEW_INVESTOR_FLG" WHEN 'Y' THEN true WHEN 'N' THEN false END
                    AS "OPEN_TO_NEW_INVESTOR_FLG",
                try_cast("PAR_VALUE" AS DECIMAL(38, 10)) AS "PAR_VALUE",
                CASE "POOLED_ASSET_FLG" WHEN 'Y' THEN true WHEN 'N' THEN false END
                    AS "POOLED_ASSET_FLG",
                try_cast("PRICE" AS DECIMAL(38, 10)) AS "PRICE",
                try_strptime("PRICE_DATE", '%Y%m%d')::DATE AS "PRICE_DATE",
                try_strptime("PRICE_UPDATE_DATE", '%Y%m%d')::DATE AS "PRICE_UPDATE_DATE",
                CASE "PTM_LEVY_FLG" WHEN 'Y' THEN true WHEN 'N' THEN false END AS "PTM_LEVY_FLG",
                CASE "QDI_ELIGIBILITY_FLAG" WHEN 'Y' THEN true WHEN 'N' THEN false END
                    AS "QDI_ELIGIBILITY_FLAG",
                try_cast("SECURITY_YIELD" AS DECIMAL(38, 10)) AS "SECURITY_YIELD",
                try_cast("SUBSEQ_MIN_INVESTMENT_AMT" AS DECIMAL(38, 10))
                    AS "SUBSEQ_MIN_INVESTMENT_AMT"
            ),
            filename AS _source_file,
            row_number() OVER (PARTITION BY filename) AS _row
        FROM read_csv(
            's3://{bucket}/sei/staged/assets/dt=*/*.out',
            delim = '|',
            header = true,
            all_varchar = true,
            filename = true,
            hive_partitioning = true,
            union_by_name = true,
            quote = '',
            escape = '',
            null_padding = true,
            max_line_size = 16000000
        )
        """,
    )


